#!/bin/bash
set -euo pipefail

# Removes the build caches (Rust, Xcode release build, Xcode test build);
# keeps the packaged app and zip in build/Release. Everything removed is regenerated by the next build.
# Usage: clean.sh             → always cleans
#        clean.sh --if-over N → cleans only if the caches exceed N GB

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TEST_DERIVED_DATA="$HOME/Library/Caches/Playfin/DerivedData"

cache_dirs() {
    find "$ROOT/core/target" "$ROOT/build" -mindepth 1 -maxdepth 1 ! -name Release 2>/dev/null || true
    [ -d "$TEST_DERIVED_DATA" ] && echo "$TEST_DERIVED_DATA" || true
}

if [ "${1:-}" = "--if-over" ]; then
    LIMIT_GB="${2:?missing size in GB}"
    CACHE_KB=$(cache_dirs | tr '\n' '\0' | xargs -0 du -sk 2>/dev/null | awk '{s += $1} END {print s + 0}')
    if [ "$CACHE_KB" -le $(( LIMIT_GB * 1024 * 1024 )) ]; then
        echo "▶ Build caches: $(( CACHE_KB / 1024 / 1024 )) GB (limit $LIMIT_GB GB), kept"
        exit 0
    fi
fi

echo "▶ Cleaning the build caches"
cargo clean --manifest-path "$ROOT/core/Cargo.toml" --quiet
cache_dirs | tr '\n' '\0' | xargs -0 rm -rf
echo "✔ Caches removed ($(du -sh "$ROOT" | cut -f1) left in the project)"
